import { readFile, writeFile } from 'node:fs/promises';

const base = new URL('./', import.meta.url);
const read = file => readFile(new URL(file, base), 'utf8');
const manifest = JSON.parse(await read('vendor-manifest.json'));
const directory = await read('directory-studio.src.js');
const metadataEnd = directory.indexOf('// ==/UserScript==') + '// ==/UserScript=='.length;
if (metadataEnd < '// ==/UserScript=='.length) throw new Error('Userscript metadata missing');
const metadata = directory.slice(0, metadataEnd);
const directoryCode = directory.slice(metadataEnd).trim();
const editor = await read('text-studio.src.js');
const mermaidSource = await read('mermaid-studio.src.js');
const mermaidRoot = 'vendor/mermaid-' + manifest.mermaid.version + '/';
const mermaidBundle = await read(mermaidRoot + manifest.mermaid.distribution);
const mermaidLicense = await read(mermaidRoot + 'LICENSE');
const cmRoot = 'vendor/codemirror-' + manifest.codemirror.version + '/';
const mdRoot = 'vendor/markdown-it-' + manifest.markdownIt.version + '/';
const stripSourceMaps = source => source.replace(/^\/\/[#@] sourceMappingURL=.*$/gm, '');
const moduleWrapper = source => '(function(module, exports, require) {\n' + stripSourceMaps(source) + '\n})(localModule, localModule.exports, localRequire);\n';
const cmLicense = await read(cmRoot + 'LICENSE');
const mdLicense = await read(mdRoot + 'LICENSE');
const licenses = '/*\nBundled offline dependencies; originals preserved under vendor/.\n' +
  'CodeMirror ' + manifest.codemirror.version + '\nSource: ' + manifest.codemirror.source + '\n' + cmLicense + '\n' +
  'markdown-it ' + manifest.markdownIt.version + '\nSource: ' + manifest.markdownIt.source + '\n' + mdLicense + '\n' +
  'Mermaid ' + manifest.mermaid.version + '\nSource: ' + manifest.mermaid.source + '\n' + mermaidLicense +
  '\nMermaid dependency license notices are preserved verbatim inside its bundled source.\n*/\n';
let factory = 'let cachedTextStudioLibraries;\nfunction createTextStudioLibraries() {\n' +
  'if (cachedTextStudioLibraries) return cachedTextStudioLibraries;\n' +
  'let localModule = { exports: {} };\n' +
  'let localRequire = () => { throw new Error("Unexpected core dependency"); };\n' +
  moduleWrapper(await read(cmRoot + 'lib/codemirror.js')) +
  'const CodeMirror = localModule.exports;\n' +
  'localRequire = () => CodeMirror;\n';
for (const file of manifest.codemirror.modules) {
  factory += '// Upstream module: ' + file + '\nlocalModule = { exports: {} };\n' + moduleWrapper(await read(cmRoot + file));
}
factory += 'localModule = { exports: {} };\n' + moduleWrapper(await read(mdRoot + manifest.markdownIt.distribution)) +
  'const MarkdownIt = localModule.exports;\n' +
  'cachedTextStudioLibraries = { CodeMirror, MarkdownIt };\nreturn cachedTextStudioLibraries;\n}\n';

// The upstream CSS has only selector blocks, media rules, and simple cursor keyframes.
// Scope selectors while preserving at-rules/keyframe steps; avoid global blink names.
function scopeEditorCSS(css) {
  return css.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\bblink\b/g, 'lts-cm-blink')
    .replace(/([^{}]+)\{([^{}]*)\}/g, (whole, selectors, body) => {
      const selector = selectors.trim();
      if (selector.startsWith('@') || /^(?:from|to|[\d.]+%)(?:\s*,\s*(?:from|to|[\d.]+%))*$/.test(selector)) return whole;
      return '\n' + selector.split(',').map(value => '#local-text-studio ' + value.trim()).join(',\n') + '{' + body + '}';
    });
}
const scopedCSS = scopeEditorCSS(await read(cmRoot + 'lib/codemirror.css'));
const payload = metadata + '\n\n// Generated by build.mjs. Edit the .src.js files, not this payload.\n' +
  licenses + '\n(() => {\n\'use strict\';\n' +
  'const TEXT_STUDIO_CODEMIRROR_CSS = ' + JSON.stringify(scopedCSS) + ';\n' +
  'function getTextStudioMermaidBundle() { return ' + JSON.stringify(mermaidBundle) + '; }\n' +
  factory + '\n' + mermaidSource + '\n' + editor + '\n' + directoryCode + '\n})();\n';
await writeFile(new URL('directory-studio.user.js', base), payload);
await writeFile(new URL('directory-studio.meta.js', base), metadata + '\n');
console.log('Generated directory-studio.user.js (' + Buffer.byteLength(payload) + ' UTF-8 bytes).');
